// 1. Obtener y DEDUPLICAR archivos de Drive (Feed y Stories) para evitar multiplicaciones
const rawFeed = $('1a. Listar Feed (Drive)').all() || [];
const feedDriveFiles = [];
const seenFeed = new Set();
for (const item of rawFeed) {
  const file = item.json;
  if (file && file.id && !seenFeed.has(file.id)) {
    seenFeed.add(file.id);
    feedDriveFiles.push(file);
  }
}

const rawStory = $('1b. Listar Stories (Drive)').all() || [];
const storyDriveFiles = [];
const seenStory = new Set();
for (const item of rawStory) {
  const file = item.json;
  if (file && file.id && !seenStory.has(file.id)) {
    seenStory.add(file.id);
    storyDriveFiles.push(file);
  }
}

// 2. Obtener historial de publicados
let publishedIds = [];
try {
  const sheetItems = $('2a. Leer Historial (Sheets)').all() || [];
  publishedIds = sheetItems
    .map(item => item.json.file_id)
    .filter(id => id && typeof id === 'string' && id.trim() !== '');
} catch (e) {
  publishedIds = [];
}

// 3. Filtrar archivos que NO estén publicados
const pendingFeed = feedDriveFiles.filter(file => !publishedIds.includes(file.id));
const pendingStory = storyDriveFiles.filter(file => !publishedIds.includes(file.id));

// Helper para calcular fecha de hoy en Argentina (UTC-3) garantizando siempre 2 dígitos (ej: "24.07")
const now = new Date();
const argentinaOffset = -3 * 60 * 60 * 1000;
const localDate = new Date(now.getTime() + argentinaOffset);
const dayStr = String(localDate.getUTCDate()).padStart(2, '0'); // "24"
const monthStr = String(localDate.getUTCMonth() + 1).padStart(2, '0'); // "07"
const todayDateStr = `${dayStr}.${monthStr}`; // "24.07"

console.log(`Fecha objetivo para hoy en Argentina: ${todayDateStr}`);

// Helper para extraer día y mes en formato estandarizado "DD.MM"
function parseFileDate(filename) {
  if (!filename) return null;
  const match = filename.match(/(?:^|[_\\-\s])(\d{1,2})[\.\-](\d{1,2})(?:[_\\-\s\.]|$)/);
  if (match) {
    const d = match[1].padStart(2, '0');
    const m = match[2].padStart(2, '0');
    return `${d}.${m}`;
  }
  return null;
}

// Helper para extraer el número de producto NumXXX
function extractProductNum(filename) {
  if (!filename) return null;
  const match = filename.match(/Num(\d+)/i);
  return match ? parseInt(match[1], 10) : null;
}

// 4. Buscar archivo para FEED correspondiente STRICTAMENTE al día de hoy (24.07)
const selectedFeedFile = pendingFeed.find(file => {
  const date = parseFileDate(file.name);
  return date === todayDateStr;
});

// 5. Buscar archivo para STORY correspondiente STRICTAMENTE al día de hoy (24.07) o al número de producto del Feed
let selectedStoryFile = pendingStory.find(file => {
  const date = parseFileDate(file.name);
  return date === todayDateStr;
});

// Si no hay por fecha exacta en Stories pero tenemos un Feed seleccionado hoy, buscar por el mismo número de producto
if (!selectedStoryFile && selectedFeedFile) {
  const targetNum = extractProductNum(selectedFeedFile.name);
  if (targetNum !== null) {
    selectedStoryFile = pendingStory.find(file => extractProductNum(file.name) === targetNum);
  }
}

// SI NO HAY ARCHIVOS PARA HOY (24.07), NO SE PUBLICA NADA
if (!selectedFeedFile && !selectedStoryFile) {
  console.log(`No hay archivos programados para hoy (${todayDateStr}). No se publicará nada.`);
  return [{
    json: {
      feed_files: [],
      story_files: [],
      file_id: '',
      file_name: '',
      product_num: null,
      message: `No hay archivos programados para el día de hoy (${todayDateStr}). No se realiza publicación.`,
      catalog_details: 'Sin publicaciones programadas para hoy.',
      matched_item: {}
    }
  }];
}

// 6. Extraer número de producto del archivo seleccionado
const targetFile = selectedFeedFile || selectedStoryFile;
const productNum = extractProductNum(targetFile.name);

// 7. Buscar detalles en el catálogo de Google Sheets
let catalogDetailsText = 'No se encontraron especificaciones para este producto en el catálogo.';
let matchedItemInfo = {};
if (productNum !== null) {
  try {
    const catalogItems = $('2b. Leer Catálogo (Sheets)').all() || [];
    const matchingRows = catalogItems
      .map(item => item.json)
      .filter(row => {
         const val = row['Num de foto'] || row.Num || row.num;
         return val !== undefined && parseInt(val, 10) === productNum;
      });

    if (matchingRows.length > 0) {
      matchedItemInfo = matchingRows[0];
      catalogDetailsText = `Detalles del Producto Num ${productNum}:\n`;
      catalogDetailsText += `Categoría/Rubro: ${matchedItemInfo.Rubro || ''}\n`;
      catalogDetailsText += `Diseño: ${matchedItemInfo.Diseño || matchedItemInfo.Diseno || ''}\n`;
      catalogDetailsText += `Color: ${matchedItemInfo.Color || ''}\n`;
      catalogDetailsText += `Características: ${matchedItemInfo.Características || matchedItemInfo.Caracteris || matchedItemInfo.Caracteristicas || ''}\n`;
      catalogDetailsText += `Incluye: ${matchedItemInfo.Incluye || ''}\n`;
      catalogDetailsText += `Precios y Medidas disponibles:\n`;

      matchingRows.forEach(row => {
        const price = row['Precio publico'] || row.Precio || row.Precio_pul || row['Precio pul'] || '';
        catalogDetailsText += `- Medida: ${row.Medida || ''} | Precio: ${price}\n`;
      });
    }
  } catch (e) {
    console.error('Error al leer el catálogo:', e);
  }
}

return [{
  json: {
    feed_files: selectedFeedFile ? [{ id: selectedFeedFile.id, name: selectedFeedFile.name }] : [],
    story_files: selectedStoryFile ? [{ id: selectedStoryFile.id, name: selectedStoryFile.name }] : [],
    file_id: selectedFeedFile ? selectedFeedFile.id : (selectedStoryFile ? selectedStoryFile.id : ''),
    file_name: selectedFeedFile ? selectedFeedFile.name : (selectedStoryFile ? selectedStoryFile.name : ''),
    product_num: productNum,
    message: `Publicación programada encontrada para hoy (${todayDateStr}).`,
    catalog_details: catalogDetailsText,
    matched_item: matchedItemInfo
  }
}];

