function getFileDate(filename) {
  if (!filename) return null;
  const match = filename.match(/(?:^|[^0-9])([0-9]{1,2})[\/\-_\.]([0-9]{1,2})(?:[^0-9]|$)/);
  if (match) {
    const p1 = parseInt(match[1], 10);
    const p2 = parseInt(match[2], 10);
    if (p1 >= 1 && p1 <= 31 && p2 >= 1 && p2 <= 12) {
      return { day: p1, month: p2 };
    }
  }
  return null;
}

function extractFileInfo(item) {
  if (!item) return null;
  const j = item.json || item;
  const id = j.id || (item.json && item.json.id) || j.fileId || j.file_id;
  const name = j.name || (item.json && item.json.name) || j.fileName || j.file_name;
  if (!id || !name) return null;
  return { id: String(id).trim(), name: String(name).trim() };
}

function getItemsFromNodes(possibleBases) {
  const suffixes = ['', '1', '2', '3', '4', '5'];
  for (const base of possibleBases) {
    for (const suffix of suffixes) {
      try {
        const fullName = base + suffix;
        const items = $(fullName).all();
        if (items && items.length > 0) return items;
      } catch(e) {}
    }
  }
  return [];
}

