}

const chosenInfo = getChosenInfo();
let files = Array.isArray(chosenInfo.feed_files) ? chosenInfo.feed_files : [];
if (files.length === 0 && chosenInfo.id && chosenInfo.is_feed_post !== false && chosenInfo.target !== 'story') {
