        });
      }
    } catch (error) {
      const errData = error.response && error.response.data ? error.response.data : error;
      const tipoStr = isVideo ? 'Reel' : 'Imagen Feed';
      throw new Error(`Meta API Error al crear contenedor de ${tipoStr}: ` + JSON.stringify(errData));
    }

    await waitForContainer(createRes.id, token, this.helpers);

    let publishRes;
    try {
      publishRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://graph.facebook.com/v19.0/${igUserId}/media_publish`,
        qs: { creation_id: createRes.id, access_token: token }
      });
    } catch (error) { 
